import type { BookCategory } from "./categories.js";

export interface Book {
  id: string;
  title: string;
  author: string;
  category: BookCategory;
  borrower: string; // empty string means the book is at home
}

export type BookInput = {
  title: string;
  author: string;
  category: BookCategory;
};

export function isLentOut(book: Book): boolean {
  return book.borrower.trim().length > 0;
}

export function normalizeBookInput(input: BookInput): BookInput {
  return {
    title: input.title.trim(),
    author: input.author.trim(),
    category: input.category,
  };
}

export function isBookInputValid(input: BookInput): boolean {
  const normalized = normalizeBookInput(input);
  return normalized.title.length > 0 && normalized.author.length > 0;
}

export const BOOK_CATEGORIES = [
  "Novel",
  "Cookbook",
  "Reference",
  "Biography",
  "Poetry",
  "History",
  "Children's",
  "Other",
] as const;

export type BookCategory = (typeof BOOK_CATEGORIES)[number];

export function isBookCategory(value: unknown): value is BookCategory {
  return (
    typeof value === "string" &&
    (BOOK_CATEGORIES as readonly string[]).includes(value)
  );
}

export function toBookCategory(value: unknown): BookCategory {
  return isBookCategory(value) ? value : "Other";
}

import type { Book } from "./types.js";
import { toBookCategory } from "./categories.js";

const STORAGE_KEY = "book-tracker.books.v1";

export interface BookRepository {
  load(): Book[];
  save(books: Book[]): void;
}

const isBrowser = typeof window !== "undefined" && window.localStorage != null;

export const localBookRepository: BookRepository = {
  load(): Book[] {
    if (!isBrowser) return [];
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed: unknown = JSON.parse(raw);
      return sanitizeBooks(parsed);
    } catch {
      return [];
    }
  },
  save(books: Book[]): void {
    if (!isBrowser) return;
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
    } catch {
      // storage may be full or unavailable; swallow quietly so the UI keeps working
    }
  },
};

function sanitizeBooks(parsed: unknown): Book[] {
  if (!Array.isArray(parsed)) return [];
  const cleaned: Book[] = [];
  for (const item of parsed) {
    const book = trySanitizeBook(item);
    if (book) cleaned.push(book);
  }
  return cleaned;
}

function trySanitizeBook(item: unknown): Book | null {
  if (typeof item !== "object" || item === null) return null;
  const raw = item as Record<string, unknown>;
  const id = typeof raw.id === "string" && raw.id.length > 0 ? raw.id : null;
  const title = typeof raw.title === "string" ? raw.title : "";
  const author = typeof raw.author === "string" ? raw.author : "";
  const category = toBookCategory(raw.category);
  const borrower =
    typeof raw.borrower === "string" ? raw.borrower.trim() : "";
  if (!id) return null;
  return { id, title, author, category, borrower };
}

export { STORAGE_KEY };

import type { Book, BookInput } from "./types.js";
import {
  isBookInputValid,
  normalizeBookInput,
} from "./types.js";
import type { BookRepository } from "./repository.js";

export interface BookService {
  getAll(): Book[];
  addBook(input: BookInput): Book;
  updateBook(id: string, input: BookInput): Book | null;
  deleteBook(id: string): void;
  lendBook(id: string, borrowerName: string): Book | null;
  returnBook(id: string): Book | null;
}

function makeId(): string {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }
  return (
    Date.now().toString(36) +
    Math.random().toString(36).slice(2, 10)
  );
}

export function createBookService(repository: BookRepository): BookService {
  let books: Book[] = repository.load();

  function persist(): void {
    repository.save(books);
  }

  function cloneBooks(): Book[] {
    return books.map((b) => ({ ...b }));
  }

  return {
    getAll(): Book[] {
      return cloneBooks();
    },
    addBook(input: BookInput): Book {
      if (!isBookInputValid(input)) {
        throw new Error("Title and author are required.");
      }
      const normalized = normalizeBookInput(input);
      const book: Book = {
        id: makeId(),
        title: normalized.title,
        author: normalized.author,
        category: normalized.category,
        borrower: "",
      };
      books = [...books, book];
      persist();
      return { ...book };
    },
    updateBook(id: string, input: BookInput): Book | null {
      if (!isBookInputValid(input)) {
        throw new Error("Title and author are required.");
      }
      const normalized = normalizeBookInput(input);
      let updated: Book | null = null;
      books = books.map((b) => {
        if (b.id !== id) return b;
        updated = {
          ...b,
          title: normalized.title,
          author: normalized.author,
          category: normalized.category,
        };
        return updated;
      });
      if (updated) persist();
      return updated ? { ...updated } : null;
    },
    deleteBook(id: string): void {
      const before = books.length;
      books = books.filter((b) => b.id !== id);
      if (books.length !== before) persist();
    },
    lendBook(id: string, borrowerName: string): Book | null {
      const name = borrowerName.trim();
      if (name.length === 0) {
        throw new Error("Enter who is borrowing the book.");
      }
      let updated: Book | null = null;
      books = books.map((b) => {
        if (b.id !== id) return b;
        updated = { ...b, borrower: name };
        return updated;
      });
      if (updated) persist();
      return updated ? { ...updated } : null;
    },
    returnBook(id: string): Book | null {
      let updated: Book | null = null;
      books = books.map((b) => {
        if (b.id !== id) return b;
        updated = { ...b, borrower: "" };
        return updated;
      });
      if (updated) persist();
      return updated ? { ...updated } : null;
    },
  };
}

import { useId, useRef, useState } from "react";
import type { FormEvent } from "react";
import type { Book, BookInput } from "./types.js";
import { BOOK_CATEGORIES, type BookCategory } from "./categories.js";
import { isBookInputValid, normalizeBookInput } from "./types.js";

interface BookFormProps {
  onSubmit: (input: BookInput) => void;
}

const emptyInput: BookInput = {
  title: "",
  author: "",
  category: "Novel",
};

export function BookForm({ onSubmit }: BookFormProps) {
  const [input, setInput] = useState<BookInput>({ ...emptyInput });
  const [error, setError] = useState<string | null>(null);
  const titleId = useId();
  const authorId = useId();
  const categoryId = useId();
  const titleRef = useRef<HTMLInputElement>(null);

  function handleSubmit(
    e: FormEvent<HTMLFormElement>,
  ): void {
    e.preventDefault();
    if (!isBookInputValid(input)) {
      setError("Title and author are required.");
      return;
    }
    setError(null);
    onSubmit(normalizeBookInput(input));
    setInput({ ...emptyInput });
    titleRef.current?.focus();
  }

  return (
    <form className="card add-form" onSubmit={handleSubmit} aria-label="Add a book">
      <h2>Add a book</h2>
      <div className="field">
        <label htmlFor={titleId}>Title</label>
        <input
          id={titleId}
          ref={titleRef}
          type="text"
          value={input.title}
          placeholder="The Faraway Tree"
          aria-required="true"
          onChange={(e) =>
            setInput((s) => ({ ...s, title: e.target.value }))
          }
        />
      </div>
      <div className="field">
        <label htmlFor={authorId}>Author</label>
        <input
          id={authorId}
          type="text"
          value={input.author}
          placeholder="Enid Blyton"
          aria-required="true"
          onChange={(e) =>
            setInput((s) => ({ ...s, author: e.target.value }))
          }
        />
      </div>
      <div className="field">
        <label htmlFor={categoryId}>Kind of book</label>
        <select
          id={categoryId}
          value={input.category}
          onChange={(e) =>
            setInput((s) => ({
              ...s,
              category: e.target.value as BookCategory,
            }))
          }
        >
          {BOOK_CATEGORIES.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
      </div>
      {error && (
        <p className="error" role="alert">
          {error}
        </p>
      )}
      <button type="submit" className="btn btn-primary">
        Add to shelf
      </button>
    </form>
  );
}

import { useId, useState } from "react";
import type { FormEvent } from "react";
import type { Book, BookInput } from "./types.js";
import { BOOK_CATEGORIES, type BookCategory } from "./categories.js";
import { isBookInputValid, normalizeBookInput } from "./types.js";

interface EditBookFormProps {
  book: Book;
  onSave: (input: BookInput) => void;
  onCancel: () => void;
}

export function EditBookForm({ book, onSave, onCancel }: EditBookFormProps) {
  const [input, setInput] = useState<BookInput>({
    title: book.title,
    author: book.author,
    category: book.category,
  });
  const [error, setError] = useState<string | null>(null);
  const titleId = useId();
  const authorId = useId();
  const categoryId = useId();

  function handleSubmit(e: FormEvent<HTMLFormElement>): void {
    e.preventDefault();
    if (!isBookInputValid(input)) {
      setError("Title and author are required.");
      return;
    }
    setError(null);
    onSave(normalizeBookInput(input));
  }

  return (
    <form className="edit-form" onSubmit={handleSubmit} aria-label={`Edit ${book.title}`}>
      <div className="field">
        <label htmlFor={titleId}>Title</label>
        <input
          id={titleId}
          type="text"
          value={input.title}
          aria-required="true"
          onChange={(e) => setInput((s) => ({ ...s, title: e.target.value }))}
        />
      </div>
      <div className="field">
        <label htmlFor={authorId}>Author</label>
        <input
          id={authorId}
          type="text"
          value={input.author}
          aria-required="true"
          onChange={(e) => setInput((s) => ({ ...s, author: e.target.value }))}
        />
      </div>
      <div className="field">
        <label htmlFor={categoryId}>Kind of book</label>
        <select
          id={categoryId}
          value={input.category}
          onChange={(e) =>
            setInput((s) => ({ ...s, category: e.target.value as BookCategory }))
          }
        >
          {BOOK_CATEGORIES.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
      </div>
      {error && (
        <p className="error" role="alert">
          {error}
        </p>
      )}
      <div className="row">
        <button type="submit" className="btn btn-primary">
          Save
        </button>
        <button type="button" className="btn" onClick={onCancel}>
          Cancel
        </button>
      </div>
    </form>
  );
}

import { useId, useState } from "react";
import type { Book } from "./types.js";
import { isLentOut } from "./types.js";
import { EditBookForm } from "./EditBookForm.js";
import type { BookInput } from "./types.js";

interface BookListProps {
  books: Book[];
  editingId: string | null;
  onStartEdit: (id: string) => void;
  onCancelEdit: () => void;
  onSaveEdit: (id: string, input: BookInput) => void;
  onDelete: (book: Book) => void;
  onLend: (id: string, borrower: string) => void;
  onReturn: (id: string) => void;
}

export function BookList({
  books,
  editingId,
  onStartEdit,
  onCancelEdit,
  onSaveEdit,
  onDelete,
  onLend,
  onReturn,
}: BookListProps) {
  if (books.length === 0) {
    return (
      <p className="empty" role="status">
        No books match this view yet.
      </p>
    );
  }

  return (
    <ul className="book-list" aria-label="Books on the shelf">
      {books.map((book) =>
        editingId === book.id ? (
          <li key={book.id} className="book-item book-item-editing">
            <EditBookForm
              book={book}
              onSave={(input) => onSaveEdit(book.id, input)}
              onCancel={onCancelEdit}
            />
          </li>
        ) : (
          <BookRow
            key={book.id}
            book={book}
            onStartEdit={() => onStartEdit(book.id)}
            onDelete={() => onDelete(book)}
            onLend={(name) => onLend(book.id, name)}
            onReturn={() => onReturn(book.id)}
          />
        ),
      )}
    </ul>
  );
}

interface BookRowProps {
  book: Book;
  onStartEdit: () => void;
  onDelete: () => void;
  onLend: (borrower: string) => void;
  onReturn: () => void;
}

function BookRow({ book, onStartEdit, onDelete, onLend, onReturn }: BookRowProps) {
  const [borrower, setBorrower] = useState("");
  const [error, setError] = useState<string | null>(null);
  const borrowerInputId = useId();
  const lent = isLentOut(book);

  function handleLend(): void {
    if (borrower.trim().length === 0) {
      setError("Enter who is borrowing the book.");
      return;
    }
    setError(null);
    onLend(borrower);
    setBorrower("");
  }

  const confirmDelete = () => {
    if (window.confirm(`Remove "${book.title}" from your shelf?`)) {
      onDelete();
    }
  };

  return (
    <li className="book-item">
      <div className="book-main">
        <h3 className="book-title">{book.title}</h3>
        <p className="book-meta">by {book.author}</p>
        <p className="book-category">{book.category}</p>
        {lent ? (
          <p className="book-status lent" data-testid="status">
            Out with {book.borrower}
          </p>
        ) : (
          <p className="book-status home" data-testid="status">
            At home
          </p>
        )}
      </div>

      <div className="book-actions">
        {!lent ? (
          <div className="lend-group">
            <label htmlFor={borrowerInputId} className="sr-only">
              Who is borrowing "{book.title}"?
            </label>
            <input
              id={borrowerInputId}
              type="text"
              value={borrower}
              placeholder="Borrower's name"
              onChange={(e) => {
                setBorrower(e.target.value);
                if (error) setError(null);
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  handleLend();
                }
              }}
            />
            <button type="button" className="btn" onClick={handleLend}>
              Lend out
            </button>
          </div>
        ) : (
          <button type="button" className="btn" onClick={onReturn}>
            Mark returned
          </button>
        )}

        <div className="row">
          <button type="button" className="btn btn-ghost" onClick={onStartEdit}>
            Edit
          </button>
          <button
            type="button"
            className="btn btn-danger"
            onClick={confirmDelete}
            aria-label={`Delete ${book.title}`}
          >
            Delete
          </button>
        </div>
        {error && (
          <p className="error" role="alert">
            {error}
          </p>
        )}
      </div>
    </li>
  );
}

import { useMemo, useState } from "react";
import type { BookInput } from "./types.js";
import type { Book } from "./types.js";
import { isLentOut } from "./types.js";
import { localBookRepository } from "./repository.js";
import { createBookService } from "./bookService.js";
import { BookForm } from "./BookForm.js";
import { BookList } from "./BookList.js";

type Filter = "all" | "out";

const service = createBookService(localBookRepository);

export function App() {
  const [books, setBooks] = useState<Book[]>(() => service.getAll());
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  function refresh(): Book[] {
    const next = service.getAll();
    setBooks(next);
    return next;
  }

  function handleAdd(input: BookInput): void {
    service.addBook(input);
    setNotice(null);
    refresh();
  }

  function handleSaveEdit(id: string, input: BookInput): void {
    service.updateBook(id, input);
    setEditingId(null);
    setNotice(null);
    refresh();
  }

  function handleDelete(book: Book): void {
    service.deleteBook(book.id);
    setNotice(null);
    refresh();
  }

  function handleLend(id: string, borrower: string): void {
    try {
      service.lendBook(id, borrower);
      setNotice(null);
      refresh();
    } catch (e) {
      setNotice(e instanceof Error ? e.message : "Could not lend the book.");
    }
  }

  function handleReturn(id: string): void {
    service.returnBook(id);
    setNotice(null);
    refresh();
  }

  const visibleBooks = useMemo(() => {
    const list = [...books];
    list.sort((a, b) =>
      a.title.localeCompare(b.title, undefined, { sensitivity: "base" }),
    );
    if (filter === "all") return list;
    return list.filter(isLentOut);
  }, [books, filter]);

  const lentCount = books.filter(isLentOut).length;
  const totalCount = books.length;

  return (
    <main className="shell">
      <header className="app-header">
        <p className="eyebrow">My shelves</p>
        <h1>Book tracker</h1>
        <p className="lede">
          Who has what, and how many are out right now.
        </p>
        <p className="counter" aria-live="polite">
          {lentCount} of {totalCount} {totalCount === 1 ? "book" : "books"} lent out
        </p>
      </header>

      <section className="layout">
        <div className="card add-card">
          <BookForm onSubmit={handleAdd} />
        </div>

        <div className="card shelf-card">
          <div className="shelf-head">
            <h2>The shelf</h2>
            <div className="filter-group" role="group" aria-label="Filter books">
              <FilterButton
                current={filter}
                value="all"
                label="All"
                onSelect={setFilter}
              />
              <FilterButton
                current={filter}
                value="out"
                label="Out"
                onSelect={setFilter}
              />
            </div>
          </div>

          {notice && (
            <p className="error" role="alert">
              {notice}
            </p>
          )}

          <BookList
            books={visibleBooks}
            editingId={editingId}
            onStartEdit={(id) => setEditingId(id)}
            onCancelEdit={() => setEditingId(null)}
            onSaveEdit={handleSaveEdit}
            onDelete={handleDelete}
            onLend={handleLend}
            onReturn={handleReturn}
          />
        </div>
      </section>
    </main>
  );
}

interface FilterButtonProps {
  current: Filter;
  value: Filter;
  label: string;
  onSelect: (f: Filter) => void;
}

function FilterButton({ current, value, label, onSelect }: FilterButtonProps) {
  const active = current === value;
  return (
    <button
      type="button"
      className={`chip ${active ? "chip-active" : ""}`}
      aria-pressed={active}
      onClick={() => onSelect(value)}
    >
      {label}
    </button>
  );
}

:root {
  color: #172033;
  background: #f4f6fb;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
}

button,
input,
select,
textarea {
  font: inherit;
}

.shell {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  min-height: 100vh;
  max-width: 64rem;
  margin: 0 auto;
  padding: clamp(1rem, 4vw, 2.5rem);
}

.app-header h1 {
  margin: 0;
  font-size: clamp(2rem, 6vw, 3rem);
  letter-spacing: -0.04em;
  line-height: 1;
}

.eyebrow {
  margin: 0 0 0.5rem;
  color: #3659c9;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.lede {
  margin: 0.5rem 0 0;
  color: #566178;
  font-size: 1.05rem;
}

.counter {
  margin: 0.75rem 0 0;
  font-weight: 600;
  color: #3659c9;
}

.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 760px) {
  .layout {
    grid-template-columns: 22rem 1fr;
    align-items: start;
  }
}

.card {
  padding: 1.25rem;
  border: 1px solid #dce2ee;
  border-radius: 1rem;
  background: #ffffff;
  box-shadow: 0 12px 40px rgb(25 38 68 / 8%);
}

.add-form h2,
.shelf-head h2 {
  margin: 0 0 1rem;
  font-size: 1.25rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 0.85rem;
}

.field label {
  font-size: 0.8rem;
  font-weight: 600;
  color: #445066;
}

.field input,
.field select {
  padding: 0.55rem 0.6rem;
  border: 1px solid #c2ccdc;
  border-radius: 0.5rem;
  background: #fff;
}

.row {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.btn {
  padding: 0.5rem 0.9rem;
  border: 1px solid #c2ccdc;
  border-radius: 0.5rem;
  background: #fff;
  color: #172033;
  cursor: pointer;
}

.btn:hover {
  border-color: #3659c9;
}

.btn-primary {
  background: #3659c9;
  border-color: #3659c9;
  color: #fff;
}

.btn-danger {
  background: #fff;
  border-color: #e6b4b4;
  color: #b3261e;
}

.btn-ghost {
  background: transparent;
}

.error {
  margin: 0.5rem 0;
  color: #b3261e;
  font-size: 0.85rem;
  font-weight: 600;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.shelf-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 0.5rem;
}

.filter-group {
  display: inline-flex;
  gap: 0.35rem;
}

.chip {
  padding: 0.4rem 0.85rem;
  border: 1px solid #c2ccdc;
  border-radius: 999px;
  background: #fff;
  cursor: pointer;
}

.chip-active {
  background: #3659c9;
  border-color: #3659c9;
  color: #fff;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.book-item {
  padding: 1rem;
  border: 1px solid #e2e7ef;
  border-radius: 0.75rem;
  background: #fafbfe;
}

.book-item-editing {
  background: #fff;
  border-color: #c7d6f0;
}

.book-main .book-title {
  margin: 0;
  font-size: 1.1rem;
}

.book-meta {
  margin: 0.15rem 0 0;
  color: #566178;
  font-size: 0.95rem;
}

.book-category {
  display: inline-block;
  margin: 0.4rem 0 0;
  padding: 0.15rem 0.5rem;
  font-size: 0.72rem;
  border-radius: 999px;
  background: #e6ecf8;
  color: #2c3e6b;
  font-weight: 600;
}

.book-status {
  margin: 0.5rem 0 0;
  font-size: 0.85rem;
  font-weight: 600;
}

.book-status.lent {
  color: #b3261e;
}

.book-status.home {
  color: #1f7a4d;
}

.book-actions {
  margin-top: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-items: flex-start;
}

.lend-group {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
  width: 100%;
}

.lend-group input {
  flex: 1 1 12rem;
  padding: 0.5rem 0.6rem;
  border: 1px solid #c2ccdc;
  border-radius: 0.5rem;
}

.empty {
  margin: 0.5rem 0;
  padding: 1.5rem;
  text-align: center;
  color: #566178;
  background: #f3f5fa;
  border: 1px dashed #c2ccdc;
  border-radius: 0.75rem;
}

.edit-form .field {
  margin-bottom: 0.7rem;
}

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { App } from "./App.js";
import type { Book } from "./types.js";

function localStorageStub() {
  let store: Record<string, string> = {};
  return {
    getItem: (key: string) => (key in store ? store[key] : null),
    setItem: (key: string, value: string) => {
      store[key] = value;
    },
    removeItem: (key: string) => {
      delete store[key];
    },
    clear: () => {
      store = {};
    },
    snapshot: () => ({ ...store }),
  };
}

describe("Book tracker", () => {
  let ls: ReturnType<typeof localStorageStub>;
  const originalLocalStorage = window.localStorage;

  beforeEach(() => {
    ls = localStorageStub();
    Object.defineProperty(window, "localStorage", {
      configurable: true,
      value: ls,
    });
  });

  afterEach(() => {
    Object.defineProperty(window, "localStorage", {
      configurable: true,
      value: originalLocalStorage,
    });
  });

  it("adds a complete book and shows it in the list", async () => {
    const user = userEvent.setup();
    render(<App />);

    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "The Faraway Tree");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "Enid Blyton");

    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    expect(
      await screen.findByRole("heading", { name: "The Faraway Tree" }),
    ).toBeInTheDocument();
    expect(screen.getByText(/by Enid Blyton/)).toBeInTheDocument();
    expect(screen.getByText("Novel")).toBeInTheDocument();
    expect(screen.getByTestId("status")).toHaveTextContent("At home");
    expect(screen.getByText(/0 of 1 books lent out/)).toBeInTheDocument();
  });

  it("blocks adding when input is invalid", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));
    expect(screen.getByRole("alert")).toHaveTextContent(
      "Title and author are required.",
    );
    expect(screen.queryByRole("listitem")).not.toBeInTheDocument();
  });

  it("edits an existing book", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Old Title");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "Old Author");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    await user.click(screen.getByRole("button", { name: "Edit" }));
    const editor = screen.getByRole("form", { name: "Edit Old Title" });
    const inputs = within(editor).getAllByRole("textbox");
    await user.clear(inputs[0]);
    await user.type(inputs[0], "New Title");
    await user.clear(inputs[1]);
    await user.type(inputs[1], "New Author");
    await user.click(within(editor).getByRole("button", { name: "Save" }));

    expect(
      await screen.findByRole("heading", { name: "New Title" }),
    ).toBeInTheDocument();
    expect(screen.getByText(/by New Author/)).toBeInTheDocument();
  });

  it("deletes a book after confirmation", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Throwaway");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "Author");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    const confirmSpy = vi
      .spyOn(window, "confirm")
      .mockReturnValue(true);

    await user.click(screen.getByRole("button", { name: "Delete Throwaway" }));

    expect(confirmSpy).toHaveBeenCalled();
    expect(screen.queryByText("Throwaway")).not.toBeInTheDocument();
    confirmSpy.mockRestore();
  });

  it("lends a book and marks it returned", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Lent Book");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "Author");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    let borrowerInput = screen.getByPlaceholderText("Borrower's name");
    await user.type(borrowerInput, "Sister");
    await user.click(screen.getByRole("button", { name: "Lend out" }));

    expect(screen.getByTestId("status")).toHaveTextContent("Out with Sister");
    expect(screen.getByText(/1 of 1 books lent out/)).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Mark returned" })).toBeInTheDocument();
    expect(screen.queryByPlaceholderText("Borrower's name")).not.toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "Mark returned" }));
    expect(await screen.findByTestId("status")).toHaveTextContent("At home");
    expect(screen.getByText(/0 of 1 books lent out/)).toBeInTheDocument();
  });

  it("blocks lending without a name", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Some Book");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "Author");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    await user.click(screen.getByRole("button", { name: "Lend out" }));
    expect(screen.getByRole("alert")).toHaveTextContent(
      "Enter who is borrowing the book.",
    );
    expect(screen.getByTestId("status")).toHaveTextContent("At home");
  });

  it("narrows the list to only books currently out", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Home Book");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "A");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Borrowed Book");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "B");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    await user.type(screen.getByPlaceholderText("Borrower's name"), "Mum");
    await user.click(screen.getByRole("button", { name: "Lend out" }));

    await user.click(screen.getByRole("button", { name: "Out", exact: true }));

    expect(screen.queryByRole("heading", { name: "Home Book" })).not.toBeInTheDocument();
    expect(
      screen.getByRole("heading", { name: "Borrowed Book" }),
    ).toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "All", exact: true }));
    expect(screen.getByRole("heading", { name: "Home Book" })).toBeInTheDocument();
    expect(
      screen.getByRole("heading", { name: "Borrowed Book" }),
    ).toBeInTheDocument();
  });

  it("shows the derived count of books lent out", async () => {
    const user = userEvent.setup();
    render(<App />);
    expect(screen.getByText(/0 of 0 books lent out/)).toBeInTheDocument();

    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "First");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "A");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Second");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "B");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    expect(screen.getByText(/0 of 2 books lent out/)).toBeInTheDocument();

    await user.type(screen.getByPlaceholderText("Borrower's name"), "Dad");
    await user.click(screen.getByRole("button", { name: "Lend out" }));
    expect(screen.getByText(/1 of 2 books lent out/)).toBeInTheDocument();
  });

  it("persists books across a reload", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(screen.getByPlaceholderText("The Faraway Tree"), "Saved Book");
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "Author");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    // Simulate a reload by re-rendering with a fresh App and same localStorage.
    const stored = ls.snapshot();

    // Reset localStorage to what was stored, then remount.
    ls.clear();
    for (const [k, v] of Object.entries(stored)) ls.setItem(k, v);

    const { unmount } = render(<App />);
    expect(
      await screen.findByRole("heading", { name: "Saved Book" }),
    ).toBeInTheDocument();
    expect(screen.getByText(/1 books? lent out/i)).toBeInTheDocument();

    unmount();
  });

  it("recovers from malformed persisted data", () => {
    ls.setItem("book-tracker.books.v1", "{not valid json");
    render(<App />);
    expect(screen.getByText(/0 of 0 books lent out/)).toBeInTheDocument();
    expect(screen.getByRole("status").textContent).toMatch(/no books/i);
  });

  it("trims whitespace when adding books", async () => {
    const user = userEvent.setup();
    render(<App />);
    await user.type(
      screen.getByPlaceholderText("The Faraway Tree"),
      "  Padded  ",
    );
    await user.type(screen.getByPlaceholderText("Enid Blyton"), "  Author  ");
    await user.click(screen.getByRole("button", { name: "Add to shelf" }));

    expect(
      await screen.findByRole("heading", { name: "Padded" }),
    ).toBeInTheDocument();
    expect(screen.getByText(/by Author/)).toBeInTheDocument();
  });

  it("treats empty result set as a valid ISBN load", async () => {
    // placeholder: empty state shows for a fresh shelf with a filter applied
    const user = userEvent.setup();
    render(<App />);
    await user.click(screen.getByRole("button", { name: "Out", exact: true }));
    expect(screen.getByRole("status")).toBeInTheDocument();
  });

  it("sanitizes persisted books with missing fields on load", () => {
    const malformed: Partial<Book>[] = [
      { id: "x", title: "OK Book", author: "Author" }, // missing category/borrower
      { id: "y" }, // missing title entirely -> still kept with empty title
    ];
    ls.setItem("book-tracker.books.v1", JSON.stringify(malformed));
    render(<App />);
    expect(screen.getByText(/2 of 2 books? lent out/i)).toBeInTheDocument();
  });
});

