import { describe, expect, it } from "vitest";
import { createBookService } from "./bookService.js";
import type { BookRepository } from "./repository.js";

function makeMemoryRepo(seeds = []) {
  let store = [...seeds];
  const repo: BookRepository = {
    load: () => store.map((b) => ({ ...b })),
    save: (books) => {
      store = books.map((b) => ({ ...b }));
    },
  };
  return { repo, store: () => store };
}

describe("BookService", () => {
  it("adds, updates, deletes, lends and returns", () => {
    const { repo, store } = makeMemoryRepo();
    const svc = createBookService(repo);

    const book = svc.addBook({
      title: "  Title  ",
      author: " Author ",
      category: "Novel",
    });
    expect(book.title).toBe("Title");
    expect(book.author).toBe("Author");
    expect(book.borrower).toBe("");
    expect(svc.getAll()).toHaveLength(1);

    const updated = svc.updateBook(book.id, {
      title: "Edited",
      author: "Editor",
      category: "Cookbook",
    });
    expect(updated?.title).toBe("Edited");
    expect(updated?.category).toBe("Cookbook");
    expect(store()[0].title).toBe("Edited");

    const lent = svc.lendBook(book.id, " Sister ");
    expect(lent?.borrower).toBe("Sister");

    expect(() => svc.lendBook(book.id, "   ")).toThrow();

    const returned = svc.returnBook(book.id);
    expect(returned?.borrower).toBe("");

    svc.deleteBook(book.id);
    expect(svc.getAll()).toHaveLength(0);
    expect(store()).toHaveLength(0);
  });

  it("rejects invalid add input", () => {
    const svc = createBookService(makeMemoryRepo().repo);
    expect(() =>
      svc.addBook({ title: "   ", author: "", category: "Novel" }),
    ).toThrow();
  });

  it("updateBook returns null for unknown id", () => {
    const svc = createBookService(makeMemoryRepo().repo);
    expect(svc.updateBook("nope", { title: "A", author: "B", category: "Novel" })).toBeNull();
  });

  it("lendBook returns null for unknown id", () => {
    const svc = createBookService(makeMemoryRepo().repo);
    expect(() => svc.lendBook("nope", "Someone")).not.toThrow();
    expect(svc.lendBook("nope", "Someone")).toBeNull();
  });
});

