import type { Book, BookInput } from "./types.js";
import {
  isBookInputValid,
  normalizeBookInput,
} from "./types.js";
import type { BookRepository } from "./repository.js";
import type { BookCategory } from "./categories.js";

export interface BookService {
  getAll(): Book[];
  addBook(input: BookInput): Book;
  updateBook(id: string, input: BookInput): Book | null;
  deleteBook(id: string): void;
  lendBook(id: string, borrowerName: string): Book | null;
  returnBook(id: string): Book | null;
}

function makeId(): string {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }
  return (
    Date.now().toString(36) +
    Math.random().toString(36).slice(2, 10)
  );
}

export function createBookService(repository: BookRepository): BookService {
  let books: Book[] = repository.load();

  function persist(): void {
    repository.save(books);
  }

  function cloneBooks(): Book[] {
    return books.map((b) => ({ ...b }));
  }

  return {
    getAll(): Book[] {
      return cloneBooks();
    },
    addBook(input: BookInput): Book {
      if (!isBookInputValid(input)) {
        throw new Error("Title and author are required.");
      }
      const normalized = normalizeBookInput(input);
      const book: Book = {
        id: makeId(),
        title: normalized.title,
        author: normalized.author,
        category: normalized.category,
        borrower: "",
      };
      books = [...books, book];
      persist();
      return { ...book };
    },
    updateBook(id: string, input: BookInput): Book | null {
      if (!isBookInputValid(input)) {
        throw new Error("Title and author are required.");
      }
      const normalized = normalizeBookInput(input);
      let found = false;
      books = books.map((b): Book => {
        if (b.id !== id) return b;
        found = true;
        return {
          ...b,
          title: normalized.title,
          author: normalized.author,
          category: normalized.category,
        };
      });
      if (!found) return null;
      persist();
      const updated = books.find((b) => b.id === id);
      return updated ? { ...updated } : null;
    },
    deleteBook(id: string): void {
      const before = books.length;
      books = books.filter((b) => b.id !== id);
      if (books.length !== before) persist();
    },
    lendBook(id: string, borrowerName: string): Book | null {
      const name = borrowerName.trim();
      if (name.length === 0) {
        throw new Error("Enter who is borrowing the book.");
      }
      const result = applyToBook(books, id, (b) => ({ ...b, borrower: name }));
      if (!result) return null;
      books = result.next;
      persist();
      return { ...result.book };
    },
    returnBook(id: string): Book | null {
      const result = applyToBook(books, id, (b) => ({ ...b, borrower: "" }));
      if (!result) return null;
      books = result.next;
      persist();
      return { ...result.book };
    },
  };
}

function applyToBook(
  list: Book[],
  id: string,
  transform: (b: Book) => Book,
): { book: Book; next: Book[] } | null {
  let found: Book | null = null;
  const next = list.map((b): Book => {
    if (b.id !== id) return b;
    found = transform(b);
    return found;
  });
  return found ? { book: found, next } : null;
}

// re-export to keep category type usage localized if needed
export type { BookCategory };

